// Minimal axios shim for our app (supports get, post, patch and interceptors.request.use)
(function (global) {
  function buildUrl(url, params) {
    if (!params) return url;
    const qs = Object.keys(params).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(params[k])).join('&');
    return url + (url.indexOf('?') === -1 ? '?' : '&') + qs;
  }

  function request(method, url, data, config) {
    return new Promise(function (resolve, reject) {
      var xhr = new XMLHttpRequest();
      var finalUrl = url;
      if (config && config.params) finalUrl = buildUrl(url, config.params);
      xhr.open(method, finalUrl, true);
      // Normalize headers: ensure single Content-Type value and merge defaults
      var hdrs = Object.assign({ 'Content-Type': 'application/json' }, (config && config.headers) || {});
      Object.keys(hdrs).forEach(function (hk) { xhr.setRequestHeader(hk, hdrs[hk]); });
      xhr.onreadystatechange = function () {
        if (xhr.readyState === 4) {
          var response = { status: xhr.status, data: null, headers: xhr.getAllResponseHeaders() };
          try { response.data = JSON.parse(xhr.responseText); } catch (e) { response.data = xhr.responseText; }
          if (xhr.status >= 200 && xhr.status < 300) resolve({ data: response.data, status: xhr.status, headers: response.headers });
          else reject({ response: response, message: 'Request failed' });
        }
      };
      xhr.onerror = function () { reject({ message: 'Network Error' }); };
      xhr.send(data ? JSON.stringify(data) : null);
    });
  }

  var interceptors = { request: { handlers: [], use: function (fn) { this.handlers.push(fn); } } };

  function applyInterceptors(config) {
    var c = config;
    interceptors.request.handlers.forEach(function (h) { try { c = h(c) || c; } catch (e) { /* ignore */ } });
    return c;
  }

  var axios = {
    interceptors: interceptors,
    get: function (url, config) { var cfg = applyInterceptors({ url: url, method: 'GET', headers: (config && config.headers) || {}, params: (config && config.params) }); return request('GET', cfg.url, null, cfg); },
    post: function (url, data, config) { var cfg = applyInterceptors({ url: url, method: 'POST', headers: (config && config.headers) || {}, params: (config && config.params) }); return request('POST', cfg.url, data, cfg); },
    patch: function (url, data, config) { var cfg = applyInterceptors({ url: url, method: 'PATCH', headers: (config && config.headers) || {}, params: (config && config.params) }); return request('PATCH', cfg.url, data, cfg); }
  };

  global.axios = axios;
})(window);
